        @Bean
        @Primary
        PrincipalRevalidator failingRevalidator() {
            return new PrincipalRevalidator(null) {
                @Override
                public boolean stillValid(AuthenticatedPrincipal p) {
                    throw new IllegalStateException("simulated revalidate dependency failure");
                }
            };
        }
    }

    @Autowired
    MockMvc mockMvc;

